// Timing and recovery are explicit: browsing chapters never declares an item lost.
const ALERTS=[];
function alertEntry(id,ch,name,kind,risk,window,action,recovery='',pickup=''){const c=C.find(c=>c.id===ch);let key='';if(kind==='Item'||kind==='Materia'){let index=c.loot.findIndex(l=>l[0]===(pickup||name));if(index<0){index=c.loot.length;c.loot.push([pickup||name,window,action,risk==='Permanent'?'missable':'important']);}key=ch+'-l'+index;}ALERTS.push({id,ch,name,kind,risk,window,action,recovery,key});}
alertEntry('iron','c2','Iron Bangle','Item','Permanent','Sector 7 · before the pillar sequence','Buy one in the Sector 7 weapon shop if keeping a complete equipment collection.','Starting armor is easy to sell accidentally; keep a spare rather than selling every copy.');
alertEntry('date','c2','Gold Saucer date choices','Event','Window','Dialogue from Midgar through the second Gold Saucer visit','Affection changes start in Midgar. Choose a target early and use a dedicated affection reference if pursuing a specific date.','One date plays per save. Barret-date trophy availability differs by port. Use a separate pre-date save to preserve the moment.');
alertEntry('flyer1','c4','Turtle’s Paradise flyer #1','Event','Optional','Sector 5 · house with sleeping child','Read the upstairs notice. Reading, rather than collecting an inventory item, advances the flyer quest.','Sector 5 can be revisited later with its key.');
alertEntry('boygil','c4','The sleeping child’s savings','Event','Window','First Sector 5 visit','Leave the hidden 5 gil untouched. On the later rescue-route visit, talk to the child for the better item reward.','Taking the gil changes the later reward; it does not block the main story.');
alertEntry('ghost','c6','Ghost Hand','Item','Window','Train Graveyard; early Battle Square reward stock','Steal from or defeat Ghost enemies before leaving the graveyard. An early Battle Square exchange is another opportunity.','Its availability closes later; secure a copy during the graveyard visit if collecting consumables.');
alertEntry('battery','c7','Keep a Battery','Event','Optional','Plate climb in Wall Market','For an unused Battery in a collection, skip the optional socket that only rewards an Ether. Use the sockets required to progress.','Using all three is normal play. This is an inventory curiosity, not required story content.');
alertEntry('element1','c8','Elemental · first password reward','Materia','Window','Shinra floor 62 · first password attempt','Solve the library clues and give the correct password on the first attempt. Save before answering.','Other Elemental copies exist; this particular reward cannot simply be retried after a wrong guess.','Elemental');
alertEntry('flyer2','c8','Turtle’s Paradise flyer #2','Event','Window','Shinra HQ lobby · two visits only','Read the lobby notice now. If using the stairs, still visit the lobby before escaping.','Last chance is the Disc 2 raid’s optional Shinra HQ detour; missing both visits loses the flyer reward quest.');
alertEntry('piano','c9','Tifa’s flashback piano flag','Event','Window','Kalm flashback · before the story ends','In Tifa’s bedroom, interact with the piano and confirm Cloud played it. This preserves an extra Elemental opportunity later.','Return to the piano while Tifa leads the party after obtaining the Highwind. This flag is separate from Final Heaven’s melody.');
alertEntry('ifrit','c11','Ifrit','Materia','Permanent','Cargo ship · before leaving the Jenova room','Pick up the red Materia after Jenova∙BIRTH. Do it before exiting the hold.','A Master Summon reward is not a replacement for owning this individual Materia.');
alertEntry('shinrabeta','c11','Shinra Beta','Item','Window','Cargo ship Marines; later underwater reactor enemies','Steal a copy from Marines aboard the ship.','There is a later reactor opportunity, so missing this early steal alone does not permanently lose the armor.');
alertEntry('ramuh','c12','Ramuh','Materia','Permanent','Corel Prison escape · jockey room before the race','Collect the red Materia in the waiting room before starting the escape race.','You cannot freely return to this waiting room afterward.');
alertEntry('umbrella','c12','Umbrella','Item','Window','Speed Square · before the Highwind story transition','Score at least 5,000 on the shooting coaster for Aeris’s weapon while the early prize list is active.','Collect on Disc 1 for practical use. Later story progression replaces the prize.');
alertEntry('gongaga','c13','Gongaga’s first-visit scenes','Event','Window','Before the second Gold Saucer Keystone sequence','Visit Gongaga’s reactor and town now for the Turks, Scarlet, and family conversations. Bring Aeris and Tifa for their relevant dialogue.','The town stays accessible, but these early scenes do not all wait for the late game.');
alertEntry('added','c13','Added Effect','Materia','Permanent','Cave of the Gi · before finishing the dungeon','Take the side route to the Materia, using care on the slippery floor.','The Cave of the Gi does not remain open for a later cleanup visit.');
alertEntry('vagyrisk','c14','Vagyrisk Claw','Item','Window','Early Fort Condor commander; low-level Bagrisk steals','An early CMD. Grand Horn can drop it. Alternatively steal from Bagrisks in the rocky Cosmo region with a sufficiently low-level thief.','High thief levels interfere with the rare steal table. Secure early for an exhaustive consumable collection; it is not needed for progression.');
alertEntry('trine1','c14','Trine · Materia Keeper opportunity','Skill','Window','Materia Keeper, then Stilva, then Godo','Equip Enemy Skill before Materia Keeper casts Trine. Keep the learner alive and win.','For all four copies, leave Godo alive until you have the fourth Enemy Skill from the Chocobo Sage.');
alertEntry('yoshiyuki','c15','Yoshiyuki','Item','Window','Rocket Town · before completing the underwater reactor','Speak repeatedly to the old man near the shops and accept his invitation to look at the rocket.','Get it on your first visit rather than depending on a later return.');
alertEntry('shotgun','c15','Shotgun','Item','Window','Rocket Town weapon shop · before the Highwind','Buy Vincent’s weapon before the shop inventory changes.','The weapon can be purchased before you recruit Vincent.');
alertEntry('mythrilclip','c10','Mythril Clip','Item','Window','Junon early weapon stock · before the Highwind','Buy a copy of Red XIII’s weapon from the early Junon shop list.','Keep starting or early equipment if collecting one of everything.');
alertEntry('fourslots','c11','Four Slots','Item','Window','Costa del Sol early shop stock · before the Highwind','Check the bar’s equipment seller and buy a copy before the later inventory change.','Its four slots can be useful early; a complete collection only needs one preserved copy.');
alertEntry('gospel','c16','Great Gospel · use before the temple ends','Event','Window','After Tiny Bronco · before completing Temple of the Ancients','Take the buggy across the sea via Costa del Sol. Visit the sleeping man beyond the eastern river with matching odd final battle-count digits for Mythril. Trade it to the weaponsmith near Gongaga and open the small upstairs box.','Teach Aeris her earlier Limits, then use the manual before the temple’s departure sequence. Obtaining a manual later cannot restore her playable window.');
for(const [id,name,location]of [['princess','Princess Guard','clock room IV'],['luck','Luck Plus','temple maze side route'],['morph','Morph','rolling-stone passage'],['bahamut','Bahamut','Red Dragon room after the fight']])alertEntry(id,'c17',name,name==='Princess Guard'?'Item':'Materia','Permanent','Temple of the Ancients · before completing the dungeon','Collect from '+location+'. Check your inventory before the final temple sequence.','The temple cannot be revisited.');
alertEntry('ribbontemple','c17','Ribbon · temple copy','Item','Window','Clock room V','Open the treasure room before the temple is destroyed.','More Ribbons are available later; this is the early temple copy.','Ribbon');
alertEntry('aerisgear','c17','Aeris’s equipment and Limit goals','Event','Window','Before completing Temple of the Ancients','Finish any desired training, weapon-use goals and Great Gospel learning before the final temple events. Save separately.','Do not assume that the Forgotten Capital is still an opportunity to train her.');
alertEntry('javelin','c20','Javelin','Item','Permanent','Gaea’s Cliff · first cave upper path','Take the right-side chest on the upper route.','The cliff is not available for a later treasure sweep.');
alertEntry('ribboncliff','c20','Ribbon · cliff copy','Item','Window','Gaea’s Cliff · hidden wall passage','Explore the invisible passage in the first cave to its chest.','Other Ribbon sources remain, but this convenient copy is a one-visit pickup.','Ribbon');
alertEntry('stilva','c20','Trine · Stilva opportunity','Skill','Window','Gaea’s Cliff · before Whirlwind Maze','Let Stilva use Trine on your Enemy Skill holders. Learn Magic Breath here too if desired.','Godo remains a Trine source if you have deliberately postponed the last pagoda fight.');
for(const [id,name]of [['neob','Neo Bahamut'],['mpturbo','MP Turbo'],['poisonring','Poison Ring']])alertEntry(id,'c21',name,name==='Poison Ring'?'Item':'Materia','Permanent','Whirlwind Maze · before the final crater scenes','Collect on the maze path before advancing through the major story event.','This part of the crater is separate from the freely explorable final dungeon.');
alertEntry('gigas','c21','Gigas Armlet','Item','Permanent','Whirlwind Maze · Gigas encounters','Steal the armor from Gigas before the story removes access to this area.','Keep time to encounter the enemy before completing the maze.');
alertEntry('earthmallet','c21','Earth Mallet','Item','Permanent','Whirlwind Maze · Gigas drops','Obtain the consumable as a drop from Gigas.','A successful steal can replace an enemy’s drop, so use separate encounters when pursuing both its armor and drop.');
alertEntry('elementpiano','c22','Elemental · Tifa’s piano copy','Materia','Window','Highwind obtained · while Tifa is party leader','Return to Tifa’s Nibelheim piano before handing leadership onward. The earlier flashback piano interaction must be set.','Other Elemental copies exist. This particular copy depends on both the flashback flag and this leadership window.');
alertEntry('mideelkey','c22','Curse Ring · old key event','Event','Window','Mideel · before its destruction','Inspect the back door in the weapon shop, then find the old key on the upper wooden walkway. Try it in the door and admit what happened when the shopkeeper asks.','A second Curse Ring can be stolen during the Mideel Ultimate Weapon battle.');
alertEntry('weaponring','c25','Curse Ring · Weapon steal','Item','Window','Ultimate Weapon’s Mideel battle only','Attempt Steal before this encounter ends.','The old-key reward is a separate opportunity, not an unlimited replacement.','Curse Ring');
alertEntry('corelhuge','c23','Huge Materia · Corel mission','Item','Permanent','North Corel train · one attempt','Save before the reactor chase and stop the train within its timer.','Failure can affect which Huge Materia the rocket later carries. It still prevents the normal four-success set.','Huge Materia · Corel');
alertEntry('warrior','c23','Warrior Bangle','Item','Permanent','Eagle Gun on the timed Corel train','Steal before defeating Eagle Gun. Budget time for attempts while keeping the train mission on schedule.','This enemy is a one-time fight. Save before starting the chase.');
alertEntry('ultima','c23','Ultima','Materia','Window','Corel train outcome','Stopping the train awards it free. Boarding but failing to stop can leave a paid purchase. Failing even to board can deny it until the relevant Huge Materia is recovered.','Reloading the pre-mission save is the clean route if you want the best outcome.');
alertEntry('condorhuge','c24','Huge Materia · Condor mission','Item','Permanent','Final Fort Condor defense','Win the strategy battle or the fallback boss fight, then speak to the old man downstairs.','Losing the fallback fight forfeits the fort. Earlier optional defenses are not required to win this mission.','Huge Materia · Condor');
alertEntry('phoenix','c24','Phoenix','Materia','Recoverable','Fort Condor summit after the final defense','Pick up the red Materia outside the summit after the hatching scene.','A missed Phoenix can be excavated at Bone Village; obtaining it here is simpler.');
for(const [id,name]of [['scales','Leviathan Scales'],['scimitar','Scimitar'],['trumpet','Battle Trumpet']])alertEntry(id,'c26',name,'Item','Permanent','Underwater reactor dock · before boarding the submarine','Open the dock chests after Carry Armor and before entering a submarine.',name==='Leviathan Scales'?'Without the scales, Oritsuru and Steal as well stay sealed behind Da-chao’s flames.':'The dock treasure route cannot be freely repeated.');
alertEntry('shinraalpha','c26','Shinra Alpha','Item','Window','Underwater reactor · senior Shinra soldiers','Steal from the SOLDIER:1st encounters before leaving the reactor sequence.','This is a late opportunity; get a copy before boarding.');
alertEntry('subhuge','c26','Huge Materia · submarine mission','Item','Permanent','Submarine battle · sink the red target','Win the minigame, then inspect the sunken red submarine with your own submarine.','Winning the battle alone does not collect its cargo.','Huge Materia · Submarine');
alertEntry('rocket','c27','Huge Materia · rocket mission','Item','Permanent','Rocket in space · before escaping','Open the security container: Confirm → Switch → Cancel → Cancel, matching your version’s control labels.','The rocket may carry an earlier missed Huge Materia; secure all four missions for the normal blue-Materia reward.','Huge Materia · Rocket');
alertEntry('zero','c27','Bahamut ZERO','Materia','Window','Blue Huge Materia in Cosmo Canyon','With the full successful Huge Materia set and both earlier Bahamut summons, inspect the blue Huge Materia.','Bone Village can offer a fallback when the blue Huge Materia was missed. Owning blue but lacking Bahamut or Neo Bahamut can block that fallback.');
alertEntry('ruderocket','c27','Ziedrich · Rocket Town steal','Item','Window','Rude before entering the rocket','Steal before the Rocket Town battle ends.','Other copies are limited to Rude’s Gelnika and Midgar encounters.','Ziedrich · rocket copy');
alertEntry('gelnikaturks','c28','Gelnika Turks encounter','Event','Window','After submarine · before completing the Midgar raid','Visit the Sunken Gelnika before the Turks stop appearing there. Steal Touph Ring from Reno and Ziedrich from Rude if desired.','The dungeon treasure stays available; the Turks encounter and these steal opportunities have a separate deadline.');
alertEntry('wutai','c29','Wutai Materia-theft story','Event','Window','With Yuffie and Tiny Bronco · finish before Disc 3','Complete the chase and Rapps rescue before the last Midgar raid is over.','The pagoda remains a separate quest. Delay Godo for Trine if you want all four Enemy Skill copies completed.');
